{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "Isradipine, a lipophilic dihydropyridine, has systemic availability of 17% in healthy volunteers after oral administration, below the 20% threshold; although structurally distant, it illustrates that lipophilic, first-pass-sensitive molecules can fall below 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Pentazocine absolute oral bioavailability is 18% in healthy subjects, below 20%, due to first-pass metabolism; again structurally distant but a lipophilic small-molecule example of low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Nifedipine, a related dihydropyridine, has F of 45±8% in healthy volunteers, above 20%, showing that lipophilic drugs can be moderately bioavailable; this opposes a blanket low-F expectation but has low structural transferability to the ubiquinone query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "low",
  "decision_summary": "The query is a ubiquinone/CoQ-type benzoquinone with a long polyisoprenoid tail, very high lipophilicity and high molecular weight. No close structural analog is present in the records; the low-F lipophilic examples are weakly supportive, and the recognized behavior of ubiquinone-type molecules is poor oral absorption, so F is expected to be below 20%.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the query molecule or a close ubiquinone analog is provided.",
    "The available records are structurally distant, so transferability is low and the prediction relies substantially on physicochemical reasoning.",
    "Formulation-dependent absorption is a major uncertainty for highly lipophilic quinones; no formulation information is supplied for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

